from datetime import date; from decimal import Decimal; from uuid import uuid4; from sqlalchemy import select; from sqlalchemy.ext.asyncio import AsyncSession; from src.extraction import BankStatementStatus, DocumentType, TransactionDirection, UploadedDocument; from src.extraction.orm.layer2 import AtomicTransaction; from src.extraction.orm.statement_summary import StatementSummary; from src.ledger import Account, AccountType; from src.reconciliation import ReconciliationMatch, ReconciliationStatus, execute_matching
class TestTransferDetectionIdempotency:
    async def _setup(self, db: AsyncSession, user_id, direction: str='OUT', file_hash_suffix: str='1'): cash = Account(user_id=user_id, name='Cash', code=f'1001_{direction}_{file_hash_suffix}', type=AccountType.ASSET, currency='SGD'); db.add(cash); await db.flush(); file_hash = f'idempotency_hash_{file_hash_suffix}'; doc = UploadedDocument(user_id=user_id, file_path=f'/tmp/test_{file_hash_suffix}.pdf', file_hash=file_hash, original_filename='test.pdf', document_type=DocumentType.BANK_STATEMENT); db.add(doc); await db.flush(); summary = StatementSummary(user_id=user_id, account_id=cash.id, uploaded_document_id=doc.id, file_hash=file_hash, institution='TestBank', account_last4='1234', currency='SGD', period_start=date(2025, 3, 1), period_end=date(2025, 3, 31), opening_balance=Decimal('0.00'), closing_balance=Decimal('0.00'), status=BankStatementStatus.PARSED); db.add(summary); await db.flush(); txn = AtomicTransaction(user_id=user_id, txn_date=date(2025, 3, 1), description='TRANSFER TO SAVINGS', amount=Decimal('500.00'), direction=TransactionDirection(direction), currency='SGD', dedup_hash=uuid4().hex + uuid4().hex, source_documents=[{'doc_id': str(doc.id), 'doc_type': DocumentType.BANK_STATEMENT.value}]); db.add(txn); await db.flush(); return (summary, txn)
    async def test_transfer_out_duplicate_detection_skipped(self, db: AsyncSession, test_user): 'AC-ledger.76.7'; user_id = test_user.id; _, txn = await self._setup(db, user_id, direction='OUT', file_hash_suffix='idem_out'); matches_first = await execute_matching(db, user_id=user_id, currency='SGD'); assert len(matches_first) == 1, 'First run should produce exactly one match'; matches_second = await execute_matching(db, user_id=user_id, currency='SGD'); assert len(matches_second) == 0, f'Second run should produce no new matches (idempotent), got {len(matches_second)}'; all_matches_result = await db.execute(select(ReconciliationMatch).where(ReconciliationMatch.atomic_txn_id == txn.id, ReconciliationMatch.status != ReconciliationStatus.SUPERSEDED)); active_matches = all_matches_result.scalars().all(); assert len(active_matches) == 1, f'Expected exactly 1 active match in DB after two runs, found {len(active_matches)}'
    async def test_transfer_in_duplicate_detection_skipped(self, db: AsyncSession, test_user): 'AC-ledger.76.7'; user_id = test_user.id; _, txn = await self._setup(db, user_id, direction='IN', file_hash_suffix='idem_in'); matches_first = await execute_matching(db, user_id=user_id, currency='SGD'); assert len(matches_first) == 1, 'First run should produce exactly one match'; matches_second = await execute_matching(db, user_id=user_id, currency='SGD'); assert len(matches_second) == 0, f'Second run should produce no new matches (idempotent), got {len(matches_second)}'; all_matches_result = await db.execute(select(ReconciliationMatch).where(ReconciliationMatch.atomic_txn_id == txn.id, ReconciliationMatch.status != ReconciliationStatus.SUPERSEDED)); active_matches = all_matches_result.scalars().all(); assert len(active_matches) == 1, f'Expected 1 active match in DB, found {len(active_matches)}'
